const { ExprError } = require('./errors');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
const FUNCTIONS = new Set(['min', 'max', 'abs']);

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const fail = (token, message) => {
    throw new ExprError(token.type === 'invalid' ? 'Unexpected character' : message, token.column);
  };
  const expect = value => {
    if (!is(value)) fail(current(), `Expected ${value}`);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function comparison() {
    const first = sum();
    if (!COMPARISONS.has(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (COMPARISONS.has(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (PRODUCTS.has(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  // Signs are collected iteratively so long sign runs do not recurse.
  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  function power() {
    const base = primary();
    if (!is('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function call(token) {
    if (!FUNCTIONS.has(token.value)) throw new ExprError('Unknown function', token.column);
    take();
    if (is(')')) throw new ExprError('Wrong argument count', token.column);
    const args = [comparison()];
    while (is(',')) {
      if (token.value === 'abs') throw new ExprError('Wrong argument count', token.column);
      take();
      args.push(comparison());
    }
    expect(')');
    return { type: 'call', name: token.value, args };
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (is('(')) return call(token);
      return { type: 'variable', name: token.value, column: token.column };
    }
    if (token.value === '(') {
